/**
 * LLM-as-judge — the SECONDARY check.
 *
 * Answers are generated by Gemini. Judgments are made by Groq. A model must not grade
 * its own output; that is not a check, it is a mirror.
 *
 * Judge disagreements never block a release (PRD §12.4). A noisy gate that blocks gets
 * disabled, which is strictly worse than a gate that warns.
 */

import { PROVIDERS } from '../worker/constants.js';

const groq = PROVIDERS.find((p) => p.id === 'groq');

const RUBRIC = `You are grading an answer written by an AI that speaks as a job candidate to a recruiter.

You are NOT checking facts — a separate mechanical layer does that. You are checking one
thing only: did the answer actually ADDRESS the question, or did it deflect, waffle, or
answer a different question?

Reply with exactly one word: ADDRESSED or DEFLECTED. Then, if DEFLECTED, one short clause
saying why.`;

export async function judge(rows) {
  const key = process.env.GROQ_API_KEY;
  if (!key) return [];

  const out = [];
  for (const r of rows) {
    if (r.status !== 'pass' || !r.answer) continue;
    try {
      const res = await fetch(groq.endpoint(), {
        method: 'POST',
        headers: { 'content-type': 'application/json', authorization: `Bearer ${key}` },
        body: JSON.stringify({
          model: groq.models[0],
          temperature: 0,
          max_tokens: 60,
          messages: [
            { role: 'system', content: RUBRIC },
            { role: 'user', content: `QUESTION: ${r.question}\n\nANSWER: ${r.answer}` },
          ],
        }),
      });
      if (!res.ok) continue;
      const j = await res.json();
      const verdict = j.choices?.[0]?.message?.content ?? '';
      if (/DEFLECTED/i.test(verdict)) {
        // Mechanical checks passed but the judge thinks the answer dodged. Worth a human
        // look, not worth blocking a release.
        out.push({ id: r.id, note: verdict.replace(/\s+/g, ' ').slice(0, 120) });
      }
    } catch {
      // A judge failure is never a release failure.
    }
  }
  return out;
}
